using System;
using System.Collections.Generic;

namespace TFM.Core
{
    /// <summary>
    /// One per-game Blowfish key. The key is the only thing that ties an archive to
    /// a title: the archive carries no game identifier of its own, so the key that
    /// successfully decrypts an entry table is how the game is identified.
    /// </summary>
    public sealed class TtArchiveKey
    {
        /// <summary>Short identifier, e.g. "Twdc". Also accepted by <see cref="TtArchiveKeys.Find"/>.</summary>
        public readonly string Id;

        /// <summary>Full title(s) that use this key, separated by " / ".</summary>
        public readonly string Games;

        /// <summary>The 56 key bytes.</summary>
        public readonly byte[] Bytes;

        public TtArchiveKey(string id, string games, byte[] bytes)
        {
            Id = id;
            Games = games;
            Bytes = bytes;
        }

        public string Label { get { return Id + "  -  " + Games; } }

        public override string ToString() { return Games; }
    }

    /// <summary>Every known Telltale archive key, with aliases for titles sharing one.</summary>
    public static class TtArchiveKeys
    {
        static readonly List<TtArchiveKey> s_all = new List<TtArchiveKey>();
        static readonly Dictionary<string, TtArchiveKey> s_lookup =
            new Dictionary<string, TtArchiveKey>(StringComparer.OrdinalIgnoreCase);

        /// <summary>Unique keys, in a stable order. Tried by auto-detection in this order.</summary>
        public static IList<TtArchiveKey> All { get { return s_all; } }

        public static int Count { get { return s_all.Count; } }

        /// <summary>Finds a key by short id or by full game title.</summary>
        public static TtArchiveKey Find(string text)
        {
            if (string.IsNullOrEmpty(text)) return null;
            TtArchiveKey key;
            return s_lookup.TryGetValue(text.Trim(), out key) ? key : null;
        }

        static void Reg(string id, string[] games, byte[] bytes)
        {
            TtArchiveKey key = new TtArchiveKey(id, Join(games), bytes);
            s_all.Add(key);
            s_lookup[id] = key;
            for (int i = 0; i < games.Length; i++)
            {
                s_lookup[games[i]] = key;
                // Also accept just the subtitle after a colon, which is how people
                // tend to refer to the episodes.
                int colon = games[i].IndexOf(": ", StringComparison.Ordinal);
                if (colon > 0) s_lookup[games[i].Substring(colon + 2)] = key;
            }
        }

        static string Join(string[] parts)
        {
            if (parts == null || parts.Length == 0) return "";
            if (parts.Length == 1) return parts[0];
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            for (int i = 0; i < parts.Length; i++)
            {
                if (i > 0) sb.Append(" / ");
                sb.Append(parts[i]);
            }
            return sb.ToString();
        }

